using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Net.Http;
using System.Security.Cryptography;
using System.Text.Json;
using System.Threading;
using System.Threading.Tasks;

namespace PatchDownload
{
    /// <summary>
    /// Representa uma entrada do arquivo patch.lua
    /// </summary>
    public class UpdateDto
    {
        public int Version { get; set; }
        public string FileName { get; set; }
        public string Integrity { get; set; }   // hash esperado (MD5/SHA1)
    }

    public class PatchService : IDisposable
    {
        private readonly HttpClient _httpClient;
        private const string BaseUrl = "https://hil-speed.hetzner.com";
        private const string PatchFolderName = "patch";

        public PatchService(HttpClient httpClient)
        {
            _httpClient = httpClient;
        }

        // --------------------------------------------------------------
        // 1️⃣ Ler o arquivo patch.lua (texto bruto)
        // --------------------------------------------------------------
        public async Task<List<UpdateDto>> LoadUpdatesAsync()
        {
            string luaContent = await File.ReadAllTextAsync(@"patch.lua");
            var updates = new List<UpdateDto>();

            // Expressão regular que captura:
            //   { Version = 1, FileName = "100MB.bin", Integrity = "741sa871sa5871sa" }, …
            // Observação: o Lua pode ter vírgulas entre as linhas.
            var pattern = @"\{ Version\s*=\s*(\d+),\s*FileName\s*=\s*\"([^\"]+)\",\s*Integrity\s*=\s*\"([^\"]+)\"\s*\};";
            var matches = System.Text.RegularExpressions.Regex.Matches(luaContent, pattern);
            foreach (Match m in matches)
            {
                int version = int.Parse(m.Groups[1].Values[0]);
                string fname = m.Groups[2].Value;
                string integrity = m.Groups[3].Value;
                updates.Add(new UpdateDto { Version = version, FileName = fname, Integrity = integrity });
            }
            return updates;
        }

        // --------------------------------------------------------------
        // 2️⃣ Garantir que a pasta “patch” exista
        // --------------------------------------------------------------
        public async Task CreateFolderAsync(string folderName)
        {
            var path = Path.Combine(Environment.CurrentDirectory, folderName);
            if (!Directory.Exists(path))
                Directory.CreateDirectory(path);
        }

        // --------------------------------------------------------------
        // 3️⃣ Baixar um arquivo (GET) com retry
        // --------------------------------------------------------------
        public async Task<bool> DownloadFileAsync(string url, string fileName, string integrity, out int progressPercent)
        {
            int maxRetries = 5;
            Random rng = new Random();

            while (true)
            {
                try
                {
                    using var response = await _httpClient.GetAsync(url, cts.Token);
                    response.EnsureSuccessStatusCode();          // 404 → thrown
                    var content = await response.Content.ReadAsStringAsync();
                    // Aproximação da porcentagem de bytes (não precisa ser precisa)
                    progressPercent = (int)(content.Length / 1024 * 100); // bytes/1KB
                    return true;
                }
                catch (HttpRequestException ex)
                {
                    // Exceções típicas: 401 (auth), 403 (forbidden), 404, timeout, etc.
                    Console.WriteLine($"[{ex.ErrorCode}] {ex.Response?.ReasonPhrase} – tentativa {++attempt}/{maxRetries}");
                    if (attempt > maxRetries) throw new Exception($"Tentativas esgotadas para {url}: {ex.Message}");
                    await Task.Delay(rng.Next(500, 3000)); // back‑off exponencial
                }
            }
        }

        // --------------------------------------------------------------
        // 4️⃣ Calcular hash SHA‑256 de um arquivo
        // --------------------------------------------------------------
        public async Task<string> ComputeHashAsync(string fileName)
        {
            using var sha256 = SHA256.Create();
            using var stream = new MemoryStream();
            using var fs = new FileStream(Path.Combine(Environment.CurrentDirectory, $"{PatchFolderName}{fileName}"),
                                        FileMode.Open, FileAccess.Read);
            await stream.CopyToAsync(stream);
            await sha256.TransformFinalOutputStream(stream, null);
            var hash = sha256.Finalize().ToArray();
            return Convert.ToHexString(hash);
        }

        // --------------------------------------------------------------
        // 5️⃣ Salvar (copiar) o conteúdo de um arquivo
        // --------------------------------------------------------------
        public async Task SaveFileAsync(string filePath, string fileName)
