            // Aqui você precisaria enviar o conteúdo para o servidor.
            // Para agora, apenas copiamos o conteúdo do disco (placeholder).
            using var dest = new FileStream(filePath, FileMode.Create, FileAccess.Write);
            // Copia o conteúdo do arquivo original (não temos o conteúdo, então ficará vazio)
            // Em produção, faça upload via API.
        }

        // --------------------------------------------------------------
        // 6️⃣ Processar todas as atualizações
        // --------------------------------------------------------------
        public async Task ProcessUpdatesAsync()
        {
            await CreateFolderAsync(PatchFolderName);

            var updates = await LoadUpdatesAsync();

            int total = updates.Count;
            int processed = 0;
            int overallPercent = 0; // porcentagem global (simples)

            foreach (var upd in updates)
            {
                string url = $"{BaseUrl}/{upd.FileName}";
                string integrity = upd.Integrity;

                // Verifica se o arquivo já está na pasta
                string targetPath = Path.Combine(Environment.CurrentDirectory, PatchFolderName, upd.FileName);
                bool fileExists = File.Exists(targetPath);

                string statusMsg = "";

                if (!fileExists)
                {
                    // --- Tentativa de download ---
                    bool ok = await DownloadFileAsync(url, upd.FileName, integrity, out int progressPercent);
                    if (ok)
                    {
                        // Verifica hash
                        string computed = await ComputeHashAsync(upd.FileName);
                        if (computed == integrity)
                        {
                            await SaveFileAsync(targetPath, upd.FileName);
                            processed++;
                            overallPercent += (int)(processed * 100 / total);
                        }
                        else
                        {
                            statusMsg = $"O arquivo já existe, mas o hash não corresponde ({computed}). Tentativa de download falhou.";
                        }
                    }
                    else
                    {
                        statusMsg = $"Erro: Arquivo não encontrado (404). Saltando em {_backoffDelay()} segundos. ";
                        await Task.Delay(_backoffDelay()); // esperar antes de seguir
                    }
                }
                else
                {
                    // Arquivo já existe – só precisa validar hash
                    if (fileExists && computed == integrity)
                    {
                        statusMsg = $"O arquivo já existe e o hash corresponde. Verificando se é necessário fazer download...";
                    }
                    else
                    {
                        statusMsg = $"O arquivo já existe, mas o hash não corresponde ({computed}). Removendo e recarregando?";
                    }
                }

                // Mostra status
                Console.WriteLine(statusMsg); // aqui você poderia atualizar #status div
            }

            Console.WriteLine($"Total processado: {processed}/{total}");
        }

        // --------------------------------------------------------------
        // Helper: back‑off aleatório (exponencial)
        // --------------------------------------------------------------
        private static int _backoffDelay()
        {
            // Exemplo: 5 s, 10 s, 20 s … até 15 s
            int delay = 5000;
            for (int i = 0; i < 5; i++) { /* não usado */ }
            return delay;
        }

        // Dispose
        public void Dispose()
        {
            // _httpClient pode ser desejado para cancelar
        }
    }
}
